package com.dramastudio.engine;
import com.dramastudio.entity.*; import com.dramastudio.gateway.ProviderProtocol.*; import com.dramastudio.repository.*; import com.dramastudio.template.NodeCatalog; import com.fasterxml.jackson.databind.ObjectMapper; import java.time.Instant; import java.util.*; import org.springframework.beans.factory.annotation.Qualifier; import org.springframework.scheduling.annotation.Async; import org.springframework.stereotype.Component;
@Component public class WorkflowExecutor {
 private static final org.slf4j.Logger log=org.slf4j.LoggerFactory.getLogger(WorkflowExecutor.class);
 private final WorkflowRunRepository runs;private final NodeRunRepository nodeRuns;private final AssetRepository assets;private final GateService gates;private final RunEventHub events;private final ObjectMapper json;private final LlmProviderAdapter llm;private final ImageProviderAdapter image;private final VideoProviderAdapter video;private final PromptBuilder prompts;
 public WorkflowExecutor(WorkflowRunRepository r,NodeRunRepository n,AssetRepository a,GateService g,RunEventHub e,ObjectMapper j,@Qualifier("mockLlm")LlmProviderAdapter mockL,@Qualifier("mockImage")ImageProviderAdapter mockI,@Qualifier("mockVideo")VideoProviderAdapter mockV,@Qualifier("aiConnectLlm")LlmProviderAdapter realL,@Qualifier("aiConnectImage")ImageProviderAdapter realI,@Qualifier("aiConnectVideo")VideoProviderAdapter realV,PromptBuilder pb,org.springframework.core.env.Environment env){runs=r;nodeRuns=n;assets=a;gates=g;events=e;json=j;prompts=pb;String key=env.getProperty("drama.aiconnect.api-key","");if(key!=null&&!key.isBlank()){llm=realL;image=realI;video=realV;log.info("Provider 模式: ai-connect (模型: {} / {} / {})",env.getProperty("drama.aiconnect.llm-model"),env.getProperty("drama.aiconnect.image-model"),env.getProperty("drama.aiconnect.video-model"));}else{llm=mockL;image=mockI;video=mockV;log.warn("Provider 模式: mock（未配置 AI_CONNECT_SK）");}}
 @Async @SuppressWarnings("unchecked") public void execute(String runId,Map<String,Object> snapshot,List<String> order){WorkflowRun run=runs.findById(runId).orElseThrow();run.status="RUNNING";run.startedAt=Instant.now().toString();runs.save(run);events.emit(runId,"RUN_STATUS_CHANGED",Map.of("status","RUNNING"));Map<String,Map<String,Object>> byId=new HashMap<>();for(var n:(List<Map<String,Object>>)snapshot.get("nodes"))byId.put(Objects.toString(n.get("id")),n);int done=0;for(String id:order){run=runs.findById(runId).orElseThrow();if(run.status.equals("CANCELED"))return;Map<String,Object> node=byId.get(id);String type=Objects.toString(node.get("type"));NodeRun nr=new NodeRun();nr.workflowRunId=runId;nr.nodeId=id;nr.nodeType=type;nr.status="QUEUED";nr.idempotencyKey=runId+":"+id+":0";nr.configSnapshotJson=write(((Map<String,Object>)node.getOrDefault("data",Map.of())).getOrDefault("config",Map.of()));nodeRuns.save(nr);events.emit(runId,"NODE_STATUS_CHANGED",Map.of("nodeId",id,"status","QUEUED"));List<String> missing=gates.missing(run.projectId,type);if(!missing.isEmpty()){nr.status="BLOCKED";nr.errorCode="GATE_BLOCKED";nr.errorMessage=String.join("; ",missing);nodeRuns.save(nr);events.emit(runId,"APPROVAL_REQUIRED",Map.of("nodeId",id,"status","BLOCKED","missingRequirements",missing));run.status="WAITING_APPROVAL";run.progress=java.math.BigDecimal.valueOf(done*100.0/order.size());runs.save(run);events.emit(runId,"RUN_STATUS_CHANGED",Map.of("status",run.status));return;}try{nr.status="RUNNING";nr.startedAt=Instant.now().toString();nr.progress=java.math.BigDecimal.TEN;nodeRuns.save(nr);events.emit(runId,"NODE_STATUS_CHANGED",Map.of("nodeId",id,"status","RUNNING"));var d=NodeCatalog.get(type);Adapter adapter=d.capability().equals("IMAGE")?image:d.capability().equals("VIDEO")?video:llm;Map<String,Object> cfg=(Map<String,Object>)((Map<String,Object>)node.getOrDefault("data",Map.of())).getOrDefault("config",Map.of());String builtPrompt=prompts.build(type,cfg,run.projectId);Request request=new Request("ai-connect",builtPrompt,"",cfg,nr.idempotencyKey);Submission sub=adapter.submit(request);nr.externalTaskId=sub.taskId();Result result=adapter.query(sub.taskId());nr.status="SUCCEEDED";nr.progress=java.math.BigDecimal.valueOf(100);nr.provider="MOCK_CLOUD";nr.model="mock-cloud";nr.finishedAt=Instant.now().toString();nodeRuns.save(nr);Asset asset=createAsset(run,nr,result);events.emit(runId,"ASSET_CREATED",Map.of("nodeId",id,"assetId",asset.id));events.emit(runId,"NODE_STATUS_CHANGED",Map.of("nodeId",id,"status","SUCCEEDED","progress",100));done++;run.progress=java.math.BigDecimal.valueOf(done*100.0/order.size());runs.save(run);}catch(Exception ex){nr.status="FAILED";nr.errorCode="PROVIDER_TIMEOUT";nr.errorMessage=ex.getMessage();nr.finishedAt=Instant.now().toString();nodeRuns.save(nr);run.status="FAILED";run.finishedAt=Instant.now().toString();runs.save(run);events.emit(runId,"NODE_STATUS_CHANGED",Map.of("nodeId",id,"status","FAILED"));return;}}run.status="SUCCEEDED";run.progress=java.math.BigDecimal.valueOf(100);run.finishedAt=Instant.now().toString();runs.save(run);events.emit(runId,"RUN_STATUS_CHANGED",Map.of("status","SUCCEEDED","progress",100));}
 private Asset createAsset(WorkflowRun run,NodeRun nr,Result result){Asset a=new Asset();a.projectId=run.projectId;a.logicalKey=nr.nodeType.toLowerCase()+":"+nr.nodeId;a.versionNo=assets.findFirstByProjectIdAndLogicalKeyOrderByVersionNoDesc(a.projectId,a.logicalKey).map(x->x.versionNo+1).orElse(1);a.assetType=outputType(nr.nodeType);a.name=nr.nodeType+" 输出 v"+a.versionNo;a.contentStatus="draft";a.contentText=result.text();a.nodeRunId=nr.id;a.createdBy=run.createdBy;return assets.save(a);}
 private String outputType(String t){return switch(t){case"PROJECT_SETUP"->"PROJECT_STATE";case"STORY_OUTLINE"->"OUTLINE";case"CHARACTER_CARD"->"CHARACTER_CARD_LIST";case"EPISODE_SCRIPT"->"EPISODE_SCRIPT";case"STORYBOARD_SCRIPT"->"SHOT_CARD_LIST";case"CHARACTER_REFERENCE_IMAGE"->"CHARACTER_REFERENCE_IMAGE";case"STORYBOARD_IMAGE"->"STORYBOARD_IMAGE";case"IMAGE_TO_VIDEO"->"SHOT_VIDEO";default->"GENERIC_OUTPUT";};}private String write(Object o){try{return json.writeValueAsString(o);}catch(Exception e){return"{}";}}
}
